window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"sl-40334","module":"shuliang","prompt":"小明、小红两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地71千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地33千米处。问A、B两地相距多少千米？","options":["142","123","96","213"],"answer":1,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且小明行71千米，故第二次相遇时小明共行213千米。213大于一个全程而小于两个全程，说明小明已从B地折返，其位置距A地为2S−213（S为全程）。由2S−213=33，解得S=123千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40335","module":"shuliang","prompt":"一项工程，师傅甲单独做需要8天完成，师傅乙单独做需要16天完成。现两人合作2天后，剩余部分由师傅乙单独完成，还需要多少天？","options":["16","14","11","10"],"answer":3,"explanation":"两人每天合作完成1/8+1/16=(8+16)/128，2天完成48/128，剩80/128；师傅乙每天完成1/16，还需16×80/128=10天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40336","module":"shuliang","prompt":"一个平底锅每次最多可以烙2张饼，每张饼两面都要烙，每面需要3分钟。烙7张饼最少需要多少分钟？","options":["42","21","24","23"],"answer":1,"explanation":"共需烙7×2=14面，每次最多烙2面，至少7锅次，最少7×3=21分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40337","module":"shuliang","prompt":"今天是星期二，再过170天是星期几？","options":["星期五","星期四","星期三","星期一"],"answer":1,"explanation":"170÷7=24余2，星期二往后推2天是星期四。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40338","module":"shuliang","prompt":"把322个名额按8:7:8的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["113","98","210","112"],"answer":3,"explanation":"总份数=8+7+8=23，每份322÷23=14个，最多的班级分得8×14=112个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40339","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供13头牛吃22天，或供21头牛吃6天。若放43头牛，可以吃多少天？","options":["4","2","6","7"],"answer":1,"explanation":"每天长草量=(21×6−13×22)÷(6−22)=10份，原有草量=13×22−10×22=66份；43头牛每天净消耗43−10=33份，可吃66÷33=2天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40340","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供17头牛吃21天，或供28头牛吃10天。若放28头牛，可以吃多少天？","options":["9","13","10","11"],"answer":2,"explanation":"每天长草量=(28×10−17×21)÷(10−21)=7份，原有草量=17×21−7×21=210份；28头牛每天净消耗28−7=21份，可吃210÷21=10天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40341","module":"shuliang","prompt":"小明和小红的速度比为8:3，两人同时同地同向出发赛跑，当小明到达终点时，小红距终点还有20米。赛道全程是多少米？","options":["1","76","32","160"],"answer":2,"explanation":"同一时间内路程比等于速度比，小红走了全程的3/8，还差全程的5/8=20米，故全程=20×8÷5=32米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40342","module":"shuliang","prompt":"某商品进价200元，售价266元。该商品的利润率是多少？","options":["32%","34%","33%","66%"],"answer":2,"explanation":"利润=266−200=66元，利润率=66÷200×100%=33%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40343","module":"shuliang","prompt":"某淘汰赛共有32支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["32","31","16","34"],"answer":1,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰31支，故共需31场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40344","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有31人，参加羽毛球赛的有21人，参加乒乓球赛的有30人；同时参加篮球和羽毛球的有9人，参加篮球和乒乓球的有12人，参加羽毛球和乒乓球的有10人，三项都参加的有6人。只参加其中一项比赛的有多少人？","options":["57","43","34","38"],"answer":3,"explanation":"只参加篮球=31−9−12+6=16人；同理只参加羽毛球=8人，只参加乒乓球=14人；合计16+8+14=38人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40345","module":"shuliang","prompt":"彩旗按“红、白、黑、蓝”的顺序循环排列，第84面彩旗是什么颜色？","options":["白","红","黑","蓝"],"answer":3,"explanation":"周期为4，84÷4=21余0，第84面旗对应周期中的第4个，即“蓝”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40346","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行39千米，按原路返回时每小时行78千米。该车往返全程的平均速度是多少千米/小时？","options":["51","58","55","52"],"answer":3,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/39+1/78)=2×39×78÷(39+78)=52千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40347","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才12岁。”乙对甲说：“当我到你这么大时，你就33岁了。”甲今年多少岁？","options":["27","19","26","24"],"answer":2,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙12岁，即乙现在为x+d；乙到甲现在这么大时甲33岁，即甲现在为y−d。由y−d−(x+d)=d得d=(33−12)÷3=7，甲今年=33−7=26岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40348","module":"shuliang","prompt":"快车和慢车的速度比为8:3，两人同时同地同向出发赛跑，当快车到达终点时，慢车距终点还有50米。赛道全程是多少米？","options":["93","80","48","400"],"answer":1,"explanation":"同一时间内路程比等于速度比，慢车走了全程的3/8，还差全程的5/8=50米，故全程=50×8÷5=80米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40349","module":"shuliang","prompt":"甲数与乙数之比为2:5，乙数与丙数之比为5:5。甲数是丙数的多少倍？","options":["11/25","5/2","2/5","7/10"],"answer":2,"explanation":"甲:丙=2×5:5×5=10:25，甲是丙的2/5倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40350","module":"shuliang","prompt":"某商品进价每件30元，售价每件50元时每天可卖240件。售价每提高1元，每天少卖4件。要使每天利润最大，售价应定为每件多少元？","options":["68","72","70","50"],"answer":2,"explanation":"设售价提高k元，每天利润=(20+k)×(240−4k)，是关于k的二次函数，当k=20时最大，此时售价=50+20=70元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40351","module":"shuliang","prompt":"已知等差数列的首项为8，公差为6，则它的第8项是多少？","options":["44","56","50","51"],"answer":2,"explanation":"等差数列第n项=首项+(n−1)×公差=8+(8-1)×6=50。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40352","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是39立方分米。圆锥的体积是多少立方分米？","options":["78","39","19","13"],"answer":3,"explanation":"等底等高的圆锥体积是圆柱的1/3，即39÷3=13立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40353","module":"shuliang","prompt":"6个正整数之和为40（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["35","40","37","34"],"answer":0,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=40−5×1=35。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40354","module":"shuliang","prompt":"时钟7点20分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["80","114","95","100"],"answer":3,"explanation":"时针与12点方向夹角为30×7+0.5×20=220.0度，分针与12点方向夹角为6×20=120度，两针夹角为100度，取小于180度的角为100.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40355","module":"shuliang","prompt":"彩旗按“甲、乙、丙、丁、戊”的顺序循环排列，第47面彩旗是什么颜色？","options":["乙","丙","甲","戊"],"answer":0,"explanation":"周期为5，47÷5=9余2，第47面旗对应周期中的第2个，即“乙”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40356","module":"shuliang","prompt":"某商品按进价加价60%定价，然后按6折出售，仍可获利。该商品的利润率是多少？","options":["4%","36%","-4%","5%"],"answer":2,"explanation":"设进价为100，售价=100×(1+60%)×6/10=96，利润率=96−100=-4%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40357","module":"shuliang","prompt":"一个长方体的长、宽、高分别为5厘米、6厘米、12厘米，它的体积是多少立方厘米？","options":["324","360","23","30"],"answer":1,"explanation":"长方体体积=长×宽×高=5×6×12=360立方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40358","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行72千米，按原路返回时每小时行36千米。该车往返全程的平均速度是多少千米/小时？","options":["47","54","51","48"],"answer":3,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/72+1/36)=2×72×36÷(72+36)=48千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40359","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供20头牛吃18天，或供32头牛吃10天。若放35头牛，可以吃多少天？","options":["11","10","8","9"],"answer":3,"explanation":"每天长草量=(32×10−20×18)÷(10−18)=5份，原有草量=20×18−5×18=270份；35头牛每天净消耗35−5=30份，可吃270÷30=9天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40360","module":"shuliang","prompt":"张三、李四两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地38千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地18千米处。问A、B两地相距多少千米？","options":["66","81","38","114"],"answer":0,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且张三行38千米，故第二次相遇时张三共行114千米。114大于一个全程而小于两个全程，说明张三已从B地折返，其位置距A地为2S−114（S为全程）。由2S−114=18，解得S=66千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40361","module":"shuliang","prompt":"两个数的和是82，差是14。这两个数中较大的数是多少？","options":["55","48","27","82"],"answer":1,"explanation":"小数=（和−差）÷2=34，大数=（和+差）÷2=48。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40362","module":"shuliang","prompt":"今天是星期日，再过120天是星期几？","options":["星期日","星期二","星期一","星期三"],"answer":2,"explanation":"120÷7=17余1，星期日往后推1天是星期一。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40363","module":"shuliang","prompt":"今年甲的年龄是乙的5倍，7年后甲的年龄是乙的3倍。乙今年多少岁？","options":["8","7","5","49"],"answer":1,"explanation":"设乙今年x岁，则甲为5x岁；7年后：5x+7=3(x+7)，解得x=7岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40364","module":"shuliang","prompt":"客车和货车分别从相距430千米的两地同时出发，相向而行。客车每小时行33千米，货车每小时行53千米，经过多少小时两车相遇？","options":["6","5","4","53"],"answer":1,"explanation":"两车速度之和为33+53=86千米/小时，相遇时间=430÷86=5小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40365","module":"shuliang","prompt":"已知等比数列的首项为3，公比为2，则它的第6项是多少？","options":["48","192","96","98"],"answer":2,"explanation":"等比数列第n项=首项×公比^(n−1)=3×2^(6-1)=96。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40366","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需42小时，逆流需66小时，两码头相距924千米。该轮船在静水中的速度是多少千米/小时？","options":["17","4","22","18"],"answer":3,"explanation":"顺流速度=924÷42=22千米/小时，逆流速度=924÷66=14千米/小时；静水速度=(22+14)÷2=18千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40367","module":"shuliang","prompt":"在一个边长为20厘米的正方形纸片内，剪一个最大的圆（圆的直径等于正方形边长，π取3.14）。剩下的纸片面积是多少平方厘米？","options":["90","400","86","81"],"answer":2,"explanation":"正方形面积=400平方厘米，最大圆半径为10厘米，圆面积=3.14×10²=314平方厘米，剩余=400−314=86平方厘米。","exam":"通用基础","__sub":"几何问题","diff":3},{"id":"sl-40368","module":"shuliang","prompt":"一项工程，甲单独做需要28天完成，乙单独做需要21天完成。两人（队）合作，需要多少天完成？","options":["25","49","7","12"],"answer":3,"explanation":"把工程总量看作1，两人效率之和为1/28+1/21=(28+21)/588，合作需要588÷(28+21)=12天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40369","module":"shuliang","prompt":"轿车在面包车后方2千米处，两人同时同向出发。轿车每小时行65千米，面包车每小时行64千米，经过多少小时轿车追上面包车？","options":["2","4","65","3"],"answer":0,"explanation":"每小时轿车比面包车多行65-64=1千米，追及时间=2÷1=2小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40370","module":"shuliang","prompt":"同一时刻，一根6米高的标杆在阳光下的影长为7米，附近一棵大树的影长为35米。这棵大树的高度是多少米？","options":["41","30","31","35"],"answer":1,"explanation":"同一时刻物高与影长成正比，树高=6×35÷7=30米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40371","module":"shuliang","prompt":"一项工程，甲的工作效率是乙的2倍，两人合作20天完成。若由甲单独做，需要多少天完成？","options":["30","20","31","28"],"answer":0,"explanation":"设乙每天完成1份，则甲每天完成2份，两人合作每天3份，工程总量为20×3=60份；甲单独做需60÷2=30天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40372","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有36人，参加数学兴趣小组的有26人，两个小组都参加的有6人。两个小组至少参加一个的共有多少人？","options":["68","62","56","10"],"answer":2,"explanation":"都参加的6人被算了两次，需减去一次，故至少参加一个的人数=36+26−6=56人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40373","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有26人，参加羽毛球赛的有24人，参加乒乓球赛的有25人；同时参加篮球和羽毛球的有7人，参加篮球和乒乓球的有6人，参加羽毛球和乒乓球的有8人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["58","47","44","45"],"answer":3,"explanation":"只参加篮球=26−7−6+4=17人；同理只参加羽毛球=13人，只参加乒乓球=15人；合计17+13+15=45人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40374","module":"shuliang","prompt":"一项工程，师傅甲单独做需要5天完成，师傅乙单独做需要20天完成。两人（队）合作，需要多少天完成？","options":["4","25","15","13"],"answer":0,"explanation":"把工程总量看作1，两人效率之和为1/5+1/20=(5+20)/100，合作需要100÷(5+20)=4天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40375","module":"shuliang","prompt":"6个正整数之和为59（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["10","13","9","12"],"answer":0,"explanation":"最大数最小时各数尽量平均，59÷6=9余5，故最大数至少为10（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40376","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供14头牛吃24天，或供32头牛吃8天。若放32头牛，可以吃多少天？","options":["11","9","7","8"],"answer":3,"explanation":"每天长草量=(32×8−14×24)÷(8−24)=5份，原有草量=14×24−5×24=216份；32头牛每天净消耗32−5=27份，可吃216÷27=8天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40377","module":"shuliang","prompt":"某商品按定价出售每件可赚60元，若按定价的8折出售，每件将亏损50元。该商品的进价是多少元？","options":["512","490","468","110"],"answer":1,"explanation":"设进价为C，定价为C+60；8折售价为8/10×(C+60)=C−50，解得C=490元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40378","module":"shuliang","prompt":"轿车、面包车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地23千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地57千米处。问A、B两地相距多少千米？","options":["69","80","35","63"],"answer":3,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且轿车行23千米，故第二次相遇时轿车共行69千米。69大于一个全程而小于两个全程，说明轿车已从B地折返，其位置距A地为2S−69（S为全程）。由2S−69=57，解得S=63千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40379","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有23人，参加羽毛球赛的有33人，参加乒乓球赛的有32人；同时参加篮球和羽毛球的有9人，参加篮球和乒乓球的有7人，参加羽毛球和乒乓球的有12人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["64","47","42","44"],"answer":3,"explanation":"只参加篮球=23−9−7+4=11人；同理只参加羽毛球=16人，只参加乒乓球=17人；合计11+16+17=44人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40380","module":"shuliang","prompt":"两个正数的和为40，要使它们的乘积最大，则最大的乘积是多少？","options":["400","40","402","397"],"answer":0,"explanation":"两数和一定时，两数相等时乘积最大，均为40÷2=20，最大乘积=20×20=400。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40381","module":"shuliang","prompt":"已知等差数列的首项为4，公差为4，则它的第11项是多少？","options":["44","48","40","45"],"answer":0,"explanation":"等差数列第n项=首项+(n−1)×公差=4+(11-1)×4=44。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40382","module":"shuliang","prompt":"甲种卡车每次可运5吨货物，耗油8升；乙种卡车每次可运3吨货物，耗油7升。现要运送35吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["77","58","53","56"],"answer":3,"explanation":"甲车每吨耗油8/5升，乙车每吨耗油7/3升，甲车更省。尽量用甲车：7车次运35吨，余0吨用乙车0次，共耗油56升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40383","module":"shuliang","prompt":"两个数的和是68，差是12。这两个数中较大的数是多少？","options":["68","46","22","40"],"answer":3,"explanation":"小数=（和−差）÷2=28，大数=（和+差）÷2=40。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40384","module":"shuliang","prompt":"今天是星期六，再过180天是星期几？","options":["星期二","星期五","星期三","星期四"],"answer":3,"explanation":"180÷7=25余5，星期六往后推5天是星期四。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40385","module":"shuliang","prompt":"一个长方形的长为30米，宽为10米，它的周长是多少米？","options":["40","300","80","82"],"answer":2,"explanation":"长方形周长=2×（长+宽）=2×(30+10)=80米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40386","module":"shuliang","prompt":"甲接水需要10分钟，乙接水需要7分钟，丙接水需要5分钟，丁接水需要6分钟，戊接水需要9分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["96","104","61","37"],"answer":2,"explanation":"让用时短的人先接水可使总等待时间最短。按5、6、7、9、10的顺序，总等待=5×4+6×3+7×2+9×1+10×0=61分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40387","module":"shuliang","prompt":"5个正整数之和为41（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["7","10","9","8"],"answer":2,"explanation":"最大数最小时各数尽量平均，41÷5=8余1，故最大数至少为9（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40388","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供11头牛吃24天，或供26头牛吃6天。若放36头牛，可以吃多少天？","options":["8","7","3","4"],"answer":3,"explanation":"每天长草量=(26×6−11×24)÷(6−24)=6份，原有草量=11×24−6×24=120份；36头牛每天净消耗36−6=30份，可吃120÷30=4天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40389","module":"shuliang","prompt":"6个正整数之和为58（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["52","58","56","53"],"answer":3,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=58−5×1=53。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40390","module":"shuliang","prompt":"袋中有4个红球和5个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["1/2","5/9","1","4/9"],"answer":3,"explanation":"共有9个球，红球4个，取到红球的概率为4/9。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40391","module":"shuliang","prompt":"4个正整数之和为30（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["30","27","29","26"],"answer":1,"explanation":"要使最大的数最大，其余3个数都取最小值1，故最大数=30−3×1=27。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40392","module":"shuliang","prompt":"甲和乙分别从相距360千米的两地同时出发，相向而行。甲每小时行34千米，乙每小时行56千米，经过多少小时两车相遇？","options":["5","4","3","56"],"answer":1,"explanation":"两车速度之和为34+56=90千米/小时，相遇时间=360÷90=4小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40393","module":"shuliang","prompt":"袋中有3个红球和4个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["3/7","4/7","1","1/2"],"answer":0,"explanation":"共有7个球，红球3个，取到红球的概率为3/7。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40394","module":"shuliang","prompt":"甲和乙分别从相距588千米的两地同时出发，相向而行。甲每小时行44千米，乙每小时行54千米，经过多少小时两车相遇？","options":["7","6","5","54"],"answer":1,"explanation":"两车速度之和为44+54=98千米/小时，相遇时间=588÷98=6小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40395","module":"shuliang","prompt":"5个正整数之和为61（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["16","13","11","12"],"answer":1,"explanation":"最大数最小时各数尽量平均，61÷5=12余1，故最大数至少为13（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40396","module":"shuliang","prompt":"甲和乙分别从相距480千米的两地同时出发，相向而行。甲每小时行33千米，乙每小时行63千米，经过多少小时两车相遇？","options":["63","6","4","5"],"answer":3,"explanation":"两车速度之和为33+63=96千米/小时，相遇时间=480÷96=5小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40397","module":"shuliang","prompt":"一项工程，老周单独做需要6天完成，老吴单独做需要10天完成。现两人合作3天后，剩余部分由老吴单独完成，还需要多少天？","options":["7","2","3","10"],"answer":1,"explanation":"两人每天合作完成1/6+1/10=(6+10)/60，3天完成48/60，剩12/60；老吴每天完成1/10，还需10×12/60=2天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40398","module":"shuliang","prompt":"某商品按定价出售每件可赚20元，若按定价的9折出售，每件将亏损30元。该商品的进价是多少元？","options":["480","516","443","50"],"answer":0,"explanation":"设进价为C，定价为C+20；9折售价为9/10×(C+20)=C−30，解得C=480元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40399","module":"shuliang","prompt":"某商品进价800元，售价1104元。该商品的利润率是多少？","options":["38%","45%","32%","76%"],"answer":0,"explanation":"利润=1104−800=304元，利润率=304÷800×100%=38%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40400","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供11头牛吃18天，或供21头牛吃9天。若放31头牛，可以吃多少天？","options":["5","8","6","7"],"answer":2,"explanation":"每天长草量=(21×9−11×18)÷(9−18)=1份，原有草量=11×18−1×18=180份；31头牛每天净消耗31−1=30份，可吃180÷30=6天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40401","module":"shuliang","prompt":"快车、慢车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地41千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地15千米处。问A、B两地相距多少千米？","options":["45","94","69","123"],"answer":2,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且快车行41千米，故第二次相遇时快车共行123千米。123大于一个全程而小于两个全程，说明快车已从B地折返，其位置距A地为2S−123（S为全程）。由2S−123=15，解得S=69千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40402","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有31人，参加羽毛球赛的有22人，参加乒乓球赛的有21人；同时参加篮球和羽毛球的有11人，参加篮球和乒乓球的有7人，参加羽毛球和乒乓球的有10人，三项都参加的有2人。只参加其中一项比赛的有多少人？","options":["23","28","24","48"],"answer":2,"explanation":"只参加篮球=31−11−7+2=15人；同理只参加羽毛球=3人，只参加乒乓球=6人；合计15+3+6=24人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40403","module":"shuliang","prompt":"A接水需要3分钟，B接水需要6分钟，C接水需要2分钟，D接水需要7分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["36","18","33","39"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按2、3、6、7的顺序，总等待=2×3+3×2+6×1+7×0=18分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40404","module":"shuliang","prompt":"甲种卡车每次可运7吨货物，耗油15升；乙种卡车每次可运3吨货物，耗油7升。现要运送35吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["76","77","71","75"],"answer":3,"explanation":"甲车每吨耗油15/7升，乙车每吨耗油7/3升，甲车更省。尽量用甲车：5车次运35吨，余0吨用乙车0次，共耗油75升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40405","module":"shuliang","prompt":"6个正整数之和为33（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["28","33","30","27"],"answer":0,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=33−5×1=28。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40406","module":"shuliang","prompt":"张三在李四后方72千米处，两人同时同向出发。张三每小时行73千米，李四每小时行37千米，经过多少小时张三追上李四？","options":["72","4","2","73"],"answer":2,"explanation":"每小时张三比李四多行73-37=36千米，追及时间=72÷36=2小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40407","module":"shuliang","prompt":"时钟7点30分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["135","60","40","45"],"answer":3,"explanation":"时针与12点方向夹角为30×7+0.5×30=225.0度，分针与12点方向夹角为6×30=180度，两针夹角为45度，取小于180度的角为45.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40408","module":"shuliang","prompt":"小明、小红两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地72千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地48千米处。问A、B两地相距多少千米？","options":["158","132","106","216"],"answer":1,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且小明行72千米，故第二次相遇时小明共行216千米。216大于一个全程而小于两个全程，说明小明已从B地折返，其位置距A地为2S−216（S为全程）。由2S−216=48，解得S=132千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40409","module":"shuliang","prompt":"已知等差数列的首项为4，公差为4，则它的第19项是多少？","options":["72","80","76","77"],"answer":2,"explanation":"等差数列第n项=首项+(n−1)×公差=4+(19-1)×4=76。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40410","module":"shuliang","prompt":"一个长方形的长为24米，宽为5米，它的面积是多少平方米？","options":["58","120","29","144"],"answer":1,"explanation":"长方形面积=长×宽=24×5=120平方米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40411","module":"shuliang","prompt":"一只手表每小时比标准时间快30秒。若以标准时间为准，这只手表一昼夜（24小时）共快多少分钟？","options":["12","15","10","24"],"answer":0,"explanation":"每小时快30秒，一昼夜24小时共快24×30=720秒=12分钟。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40412","module":"shuliang","prompt":"时钟11点30分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["165","170","155","15"],"answer":0,"explanation":"时针与12点方向夹角为30×11+0.5×30=345.0度，分针与12点方向夹角为6×30=180度，两针夹角为165度，取小于180度的角为165.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40413","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供12头牛吃21天，或供30头牛吃7天。若放30头牛，可以吃多少天？","options":["10","7","6","9"],"answer":1,"explanation":"每天长草量=(30×7−12×21)÷(7−21)=3份，原有草量=12×21−3×21=189份；30头牛每天净消耗30−3=27份，可吃189÷27=7天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40414","module":"shuliang","prompt":"一列火车长233米，以每秒36米的速度通过一座长1620米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["45","6","51","54"],"answer":2,"explanation":"火车完全过桥需行驶233+1620=1853米，时间=1853÷36=51秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40415","module":"shuliang","prompt":"已知等差数列的前10项和为350，前20项和为1300，则该数列的公差是多少？","options":["5","7","6","1"],"answer":2,"explanation":"S20−2×S10=(1300)−2×(350)=600=100d（第11到20项之和比前10项之和多100d），故d=6。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40416","module":"shuliang","prompt":"客车和货车分别从相距580千米的两地同时出发，相向而行。客车每小时行62千米，货车每小时行54千米，经过多少小时两车相遇？","options":["4","6","5","62"],"answer":2,"explanation":"两车速度之和为62+54=116千米/小时，相遇时间=580÷116=5小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40417","module":"shuliang","prompt":"甲种卡车每次可运8吨货物，耗油10升；乙种卡车每次可运3吨货物，耗油4升。现要运送64吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["84","86","76","80"],"answer":3,"explanation":"甲车每吨耗油10/8升，乙车每吨耗油4/3升，甲车更省。尽量用甲车：8车次运64吨，余0吨用乙车0次，共耗油80升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40418","module":"shuliang","prompt":"甲种卡车每次可运7吨货物，耗油13升；乙种卡车每次可运3吨货物，耗油8升。现要运送56吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["104","108","100","144"],"answer":0,"explanation":"甲车每吨耗油13/7升，乙车每吨耗油8/3升，甲车更省。尽量用甲车：8车次运56吨，余0吨用乙车0次，共耗油104升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40419","module":"shuliang","prompt":"袋中有8个红球和4个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["1","1/3","2/3","1/2"],"answer":2,"explanation":"共有12个球，红球8个，取到红球的概率为8/12=2/3。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40420","module":"shuliang","prompt":"一个正方形的边长扩大到原来的3倍，它的面积扩大到原来的多少倍？","options":["3","9","6","12"],"answer":1,"explanation":"边长扩大3倍，面积扩大3×3=9倍。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40421","module":"shuliang","prompt":"某淘汰赛共有8支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["7","8","4","10"],"answer":0,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰7支，故共需7场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40422","module":"shuliang","prompt":"5个正整数之和为36（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["33","36","31","32"],"answer":3,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=36−4×1=32。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40423","module":"shuliang","prompt":"甲种卡车每次可运8吨货物，耗油14升；乙种卡车每次可运2吨货物，耗油5升。现要运送56吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["98","100","94","140"],"answer":0,"explanation":"甲车每吨耗油14/8升，乙车每吨耗油5/2升，甲车更省。尽量用甲车：7车次运56吨，余0吨用乙车0次，共耗油98升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40424","module":"shuliang","prompt":"客车和货车的速度比为7:2，两人同时同地同向出发赛跑，当客车到达终点时，货车距终点还有60米。赛道全程是多少米？","options":["84","97","47","420"],"answer":0,"explanation":"同一时间内路程比等于速度比，货车走了全程的2/7，还差全程的5/7=60米，故全程=60×7÷5=84米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40425","module":"shuliang","prompt":"同一时刻，一根4米高的标杆在阳光下的影长为7米，附近一棵大树的影长为35米。这棵大树的高度是多少米？","options":["39","20","21","35"],"answer":1,"explanation":"同一时刻物高与影长成正比，树高=4×35÷7=20米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40426","module":"shuliang","prompt":"袋中有3个红球和2个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["1/2","2/5","1","3/5"],"answer":3,"explanation":"共有5个球，红球3个，取到红球的概率为3/5。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40427","module":"shuliang","prompt":"某商品进价600元，售价1116元。该商品的利润率是多少？","options":["86%","92%","79%","172%"],"answer":0,"explanation":"利润=1116−600=516元，利润率=516÷600×100%=86%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40428","module":"shuliang","prompt":"4个正整数之和为43（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["10","14","11","12"],"answer":2,"explanation":"最大数最小时各数尽量平均，43÷4=10余3，故最大数至少为11（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40429","module":"shuliang","prompt":"快车在慢车后方3千米处，两人同时同向出发。快车每小时行73千米，慢车每小时行72千米，经过多少小时快车追上慢车？","options":["3","4","5","73"],"answer":0,"explanation":"每小时快车比慢车多行73-72=1千米，追及时间=3÷1=3小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40430","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才11岁。”乙对甲说：“当我到你这么大时，你就53岁了。”甲今年多少岁？","options":["37","25","40","39"],"answer":3,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙11岁，即乙现在为x+d；乙到甲现在这么大时甲53岁，即甲现在为y−d。由y−d−(x+d)=d得d=(53−11)÷3=14，甲今年=53−14=39岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40431","module":"shuliang","prompt":"某商品进价每件30元，售价每件70元时每天可卖150件。售价每提高1元，每天少卖3件。要使每天利润最大，售价应定为每件多少元？","options":["78","75","74","70"],"answer":1,"explanation":"设售价提高k元，每天利润=(40+k)×(150−3k)，是关于k的二次函数，当k=5时最大，此时售价=70+5=75元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40432","module":"shuliang","prompt":"一项工程，师傅甲单独做需要20天完成，师傅乙单独做需要30天完成。两人（队）合作，需要多少天完成？","options":["12","50","10","25"],"answer":0,"explanation":"把工程总量看作1，两人效率之和为1/20+1/30=(20+30)/600，合作需要600÷(20+30)=12天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40433","module":"shuliang","prompt":"一个平底锅每次最多可以烙4张饼，每张饼两面都要烙，每面需要2分钟。烙7张饼最少需要多少分钟？","options":["11","28","8","7"],"answer":2,"explanation":"共需烙7×2=14面，每次最多烙4面，至少4锅次，最少4×2=8分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40434","module":"shuliang","prompt":"张三和李四分别从相距460千米的两地同时出发，相向而行。张三每小时行62千米，李四每小时行53千米，经过多少小时两车相遇？","options":["5","6","3","4"],"answer":3,"explanation":"两车速度之和为62+53=115千米/小时，相遇时间=460÷115=4小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40435","module":"shuliang","prompt":"一个长方形的长为14米，宽为23米，它的面积是多少平方米？","options":["322","74","37","336"],"answer":0,"explanation":"长方形面积=长×宽=14×23=322平方米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40436","module":"shuliang","prompt":"今年父子二人年龄之和是160岁，父亲年龄是儿子年龄的4倍。父亲今年多少岁？","options":["126","32","130","128"],"answer":3,"explanation":"儿子年龄为1份，父亲为4份，共5份；儿子=160÷5=32岁，父亲=4×32=128岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40437","module":"shuliang","prompt":"一项工程，一队单独做需要10天完成，二队单独做需要28天完成。现两人合作5天后，剩余部分由二队单独完成，还需要多少天？","options":["23","9","10","28"],"answer":1,"explanation":"两人每天合作完成1/10+1/28=(10+28)/280，5天完成190/280，剩90/280；二队每天完成1/28，还需28×90/280=9天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40438","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需54小时，逆流需84小时，两码头相距1512千米。该轮船在静水中的速度是多少千米/小时？","options":["28","5","23","21"],"answer":2,"explanation":"顺流速度=1512÷54=28千米/小时，逆流速度=1512÷84=18千米/小时；静水速度=(28+18)÷2=23千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40439","module":"shuliang","prompt":"时钟9点10分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["138","156","145","35"],"answer":2,"explanation":"时针与12点方向夹角为30×9+0.5×10=275.0度，分针与12点方向夹角为6×10=60度，两针夹角为215度，取小于180度的角为145.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40440","module":"shuliang","prompt":"甲种卡车每次可运8吨货物，耗油9升；乙种卡车每次可运2吨货物，耗油6升。现要运送96吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["288","115","104","108"],"answer":3,"explanation":"甲车每吨耗油9/8升，乙车每吨耗油6/2升，甲车更省。尽量用甲车：12车次运96吨，余0吨用乙车0次，共耗油108升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40441","module":"shuliang","prompt":"一个平底锅每次最多可以烙4张饼，每张饼两面都要烙，每面需要3分钟。烙8张饼最少需要多少分钟？","options":["11","48","13","12"],"answer":3,"explanation":"共需烙8×2=16面，每次最多烙4面，至少4锅次，最少4×3=12分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40442","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有43人，参加数学兴趣小组的有39人，两个小组都参加的有17人。两个小组至少参加一个的共有多少人？","options":["99","82","65","4"],"answer":2,"explanation":"都参加的17人被算了两次，需减去一次，故至少参加一个的人数=43+39−17=65人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40443","module":"shuliang","prompt":"某商品进价每件30元，售价每件60元时每天可卖156件。售价每提高1元，每天少卖3件。要使每天利润最大，售价应定为每件多少元？","options":["60","74","70","71"],"answer":3,"explanation":"设售价提高k元，每天利润=(30+k)×(156−3k)，是关于k的二次函数，当k=11时最大，此时售价=60+11=71元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40444","module":"shuliang","prompt":"甲种卡车每次可运6吨货物，耗油8升；乙种卡车每次可运3吨货物，耗油5升。现要运送24吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["40","38","30","32"],"answer":3,"explanation":"甲车每吨耗油8/6升，乙车每吨耗油5/3升，甲车更省。尽量用甲车：4车次运24吨，余0吨用乙车0次，共耗油32升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40445","module":"shuliang","prompt":"已知等差数列的首项为10，公差为3，则它的前16项之和是多少？","options":["520","880","524","515"],"answer":0,"explanation":"第16项=10+(16-1)×3=55，前16项和=n×(首项+末项)÷2=16×(10+55)÷2=520。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40446","module":"shuliang","prompt":"甲种卡车每次可运7吨货物，耗油15升；乙种卡车每次可运2吨货物，耗油7升。现要运送35吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["71","78","75","119"],"answer":2,"explanation":"甲车每吨耗油15/7升，乙车每吨耗油7/2升，甲车更省。尽量用甲车：5车次运35吨，余0吨用乙车0次，共耗油75升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40447","module":"shuliang","prompt":"客车、货车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地28千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地72千米处。问A、B两地相距多少千米？","options":["56","91","78","84"],"answer":2,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且客车行28千米，故第二次相遇时客车共行84千米。84大于一个全程而小于两个全程，说明客车已从B地折返，其位置距A地为2S−84（S为全程）。由2S−84=72，解得S=78千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40448","module":"shuliang","prompt":"某班共有42人，参加数学竞赛的有18人，参加作文竞赛的有15人，参加英语竞赛的有23人；同时参加数学和作文的有7人，参加数学和英语的有4人，参加作文和英语的有9人，三项都参加的有2人。三项竞赛都不参加的有多少人？","options":["42","8","20","4"],"answer":3,"explanation":"至少参加一项的有18+15+23−7−4−9+2=38人，都不参加的有42−38=4人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40449","module":"shuliang","prompt":"小明、小红两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地42千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地60千米处。问A、B两地相距多少千米？","options":["107","93","82","126"],"answer":1,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且小明行42千米，故第二次相遇时小明共行126千米。126大于一个全程而小于两个全程，说明小明已从B地折返，其位置距A地为2S−126（S为全程）。由2S−126=60，解得S=93千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40450","module":"shuliang","prompt":"6个正整数之和为41（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["35","41","39","36"],"answer":3,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=41−5×1=36。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40451","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才5岁。”乙对甲说：“当我到你这么大时，你就44岁了。”甲今年多少岁？","options":["31","18","33","29"],"answer":0,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙5岁，即乙现在为x+d；乙到甲现在这么大时甲44岁，即甲现在为y−d。由y−d−(x+d)=d得d=(44−5)÷3=13，甲今年=44−13=31岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40452","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有27人，参加数学兴趣小组的有26人，两个小组都参加的有11人。两个小组至少参加一个的共有多少人？","options":["42","53","64","1"],"answer":0,"explanation":"都参加的11人被算了两次，需减去一次，故至少参加一个的人数=27+26−11=42人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40453","module":"shuliang","prompt":"某小组共有12名成员，现从中随机选出5名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["543","792","252","540"],"answer":3,"explanation":"从12人中选5人共C(12,5)=792种；甲、乙都不入选有C(10,5)=252种；故至少一人入选共792−252=540种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40454","module":"shuliang","prompt":"某商场促销“满300减90”，小明购买了标价1500元的商品（满足优惠条件）。实际付款相当于打几折？","options":["3折","8折","6折","7折"],"answer":3,"explanation":"优惠后实付1500−5×90=1050元，1050÷1500=7/10，相当于打7折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40455","module":"shuliang","prompt":"某班共有60人，参加数学竞赛的有22人，参加作文竞赛的有30人，参加英语竞赛的有25人；同时参加数学和作文的有9人，参加数学和英语的有8人，参加作文和英语的有8人，三项都参加的有2人。三项竞赛都不参加的有多少人？","options":["25","7","6","60"],"answer":2,"explanation":"至少参加一项的有22+30+25−9−8−8+2=54人，都不参加的有60−54=6人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40456","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供11头牛吃18天，或供17头牛吃6天。若放35头牛，可以吃多少天？","options":["4","2","6","3"],"answer":1,"explanation":"每天长草量=(17×6−11×18)÷(6−18)=8份，原有草量=11×18−8×18=54份；35头牛每天净消耗35−8=27份，可吃54÷27=2天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40457","module":"shuliang","prompt":"甲数与乙数之比为4:3，乙数与丙数之比为3:5。甲数是丙数的多少倍？","options":["13/15","5/4","4/5","20/9"],"answer":2,"explanation":"甲:丙=4×3:3×5=12:15，甲是丙的4/5倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40458","module":"shuliang","prompt":"某班共有50人，参加数学竞赛的有22人，参加作文竞赛的有23人，参加英语竞赛的有19人；同时参加数学和作文的有10人，参加数学和英语的有9人，参加作文和英语的有8人，三项都参加的有5人。三项竞赛都不参加的有多少人？","options":["50","9","27","8"],"answer":3,"explanation":"至少参加一项的有22+23+19−10−9−8+5=42人，都不参加的有50−42=8人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40459","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供18头牛吃24天，或供32头牛吃8天。若放35头牛，可以吃多少天？","options":["7","10","6","13"],"answer":0,"explanation":"每天长草量=(32×8−18×24)÷(8−24)=11份，原有草量=18×24−11×24=168份；35头牛每天净消耗35−11=24份，可吃168÷24=7天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40460","module":"shuliang","prompt":"已知等比数列的首项为4，公比为3，则它的第7项是多少？","options":["8748","2916","972","2919"],"answer":1,"explanation":"等比数列第n项=首项×公比^(n−1)=4×3^(7-1)=2916。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40461","module":"shuliang","prompt":"同一时刻，一根4米高的标杆在阳光下的影长为8米，附近一棵大树的影长为32米。这棵大树的高度是多少米？","options":["17","36","16","32"],"answer":2,"explanation":"同一时刻物高与影长成正比，树高=4×32÷8=16米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40462","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才5岁。”乙对甲说：“当我到你这么大时，你就41岁了。”甲今年多少岁？","options":["29","17","30","28"],"answer":0,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙5岁，即乙现在为x+d；乙到甲现在这么大时甲41岁，即甲现在为y−d。由y−d−(x+d)=d得d=(41−5)÷3=12，甲今年=41−12=29岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40463","module":"shuliang","prompt":"一项工程，老周先做8天、老吴再做14天恰好完成；若老吴先做8天、老周再做14天也恰好完成。两人合作，需要多少天完成？","options":["6","22","11","12"],"answer":2,"explanation":"设老周每天完成x、老吴每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=22÷2=11天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40464","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有31人，参加数学兴趣小组的有16人，两个小组都参加的有6人。两个小组至少参加一个的共有多少人？","options":["41","47","53","15"],"answer":0,"explanation":"都参加的6人被算了两次，需减去一次，故至少参加一个的人数=31+16−6=41人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40465","module":"shuliang","prompt":"袋中有2个红球和8个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["1","4/5","1/5","1/2"],"answer":2,"explanation":"共有10个球，红球2个，取到红球的概率为2/10=1/5。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40466","module":"shuliang","prompt":"两个数的和是210，差是36。这两个数中较大的数是多少？","options":["210","141","69","123"],"answer":3,"explanation":"小数=（和−差）÷2=87，大数=（和+差）÷2=123。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40467","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是36立方分米。圆锥的体积是多少立方分米？","options":["12","36","18","72"],"answer":0,"explanation":"等底等高的圆锥体积是圆柱的1/3，即36÷3=12立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40468","module":"shuliang","prompt":"某商品进价400元，售价740元。该商品的利润率是多少？","options":["82%","91%","85%","170%"],"answer":2,"explanation":"利润=740−400=340元，利润率=340÷400×100%=85%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40469","module":"shuliang","prompt":"某班共有50人，参加数学竞赛的有17人，参加作文竞赛的有21人，参加英语竞赛的有21人；同时参加数学和作文的有8人，参加数学和英语的有4人，参加作文和英语的有9人，三项都参加的有4人。三项竞赛都不参加的有多少人？","options":["12","8","21","50"],"answer":1,"explanation":"至少参加一项的有17+21+21−8−4−9+4=42人，都不参加的有50−42=8人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40470","module":"shuliang","prompt":"轿车、面包车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地40千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地48千米处。问A、B两地相距多少千米？","options":["84","101","60","120"],"answer":0,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且轿车行40千米，故第二次相遇时轿车共行120千米。120大于一个全程而小于两个全程，说明轿车已从B地折返，其位置距A地为2S−120（S为全程）。由2S−120=48，解得S=84千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40471","module":"shuliang","prompt":"某单位组织115人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["1200","1242","985","1080"],"answer":3,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为1080元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40472","module":"shuliang","prompt":"轿车在面包车后方9千米处，两人同时同向出发。轿车每小时行85千米，面包车每小时行76千米，经过多少小时轿车追上面包车？","options":["85","3","9","1"],"answer":3,"explanation":"每小时轿车比面包车多行85-76=9千米，追及时间=9÷9=1小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40473","module":"shuliang","prompt":"A接水需要11分钟，B接水需要6分钟，C接水需要3分钟，D接水需要8分钟，E接水需要2分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["30","73","61","37"],"answer":3,"explanation":"让用时短的人先接水可使总等待时间最短。按2、3、6、8、11的顺序，总等待=2×4+3×3+6×2+8×1+11×0=37分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40474","module":"shuliang","prompt":"某商品进价200元，售价246元。该商品的利润率是多少？","options":["26%","23%","21%","46%"],"answer":1,"explanation":"利润=246−200=46元，利润率=46÷200×100%=23%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40475","module":"shuliang","prompt":"抽屉里有5种不同颜色的手套（每种数量都足够多），至少取出多少只才能保证有一副颜色相同的手套？","options":["10","5","9","6"],"answer":3,"explanation":"考虑最不利情形：每种颜色各取1只共5只仍无同色一副，再取1只必与某只同色，故至少取6只。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40476","module":"shuliang","prompt":"一项工程，王师傅先做15天、赵师傅再做11天恰好完成；若赵师傅先做15天、王师傅再做11天也恰好完成。两人合作，需要多少天完成？","options":["4","26","13","14"],"answer":2,"explanation":"设王师傅每天完成x、赵师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=26÷2=13天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40477","module":"shuliang","prompt":"甲种卡车每次可运6吨货物，耗油10升；乙种卡车每次可运2吨货物，耗油5升。现要运送24吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["36","43","40","60"],"answer":2,"explanation":"甲车每吨耗油10/6升，乙车每吨耗油5/2升，甲车更省。尽量用甲车：4车次运24吨，余0吨用乙车0次，共耗油40升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40478","module":"shuliang","prompt":"某淘汰赛共有23支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["11","23","22","25"],"answer":2,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰22支，故共需22场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40479","module":"shuliang","prompt":"某淘汰赛共有18支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["18","17","9","20"],"answer":1,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰17支，故共需17场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40480","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才9岁。”乙对甲说：“当我到你这么大时，你就24岁了。”甲今年多少岁？","options":["20","14","19","18"],"answer":2,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙9岁，即乙现在为x+d；乙到甲现在这么大时甲24岁，即甲现在为y−d。由y−d−(x+d)=d得d=(24−9)÷3=5，甲今年=24−5=19岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40481","module":"shuliang","prompt":"一个长方体的长、宽、高分别为9厘米、2厘米、9厘米，它的表面积是多少平方厘米？","options":["40","162","20","234"],"answer":3,"explanation":"长方体表面积=2×（长×宽+宽×高+长×高）=2×(18+18+81)=234平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40482","module":"shuliang","prompt":"4个正整数之和为42（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["42","39","40","38"],"answer":1,"explanation":"要使最大的数最大，其余3个数都取最小值1，故最大数=42−3×1=39。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40483","module":"shuliang","prompt":"6个正整数之和为39（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["39","34","37","33"],"answer":1,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=39−5×1=34。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40484","module":"shuliang","prompt":"已知等差数列的前10项和为175，前20项和为650，则该数列的公差是多少？","options":["2","4","3","1"],"answer":2,"explanation":"S20−2×S10=(650)−2×(175)=300=100d（第11到20项之和比前10项之和多100d），故d=3。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40485","module":"shuliang","prompt":"今年父子二人年龄之和是140岁，父亲年龄是儿子年龄的3倍。父亲今年多少岁？","options":["100","35","109","105"],"answer":3,"explanation":"儿子年龄为1份，父亲为3份，共4份；儿子=140÷4=35岁，父亲=3×35=105岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40486","module":"shuliang","prompt":"某班共有52人，参加数学竞赛的有29人，参加作文竞赛的有15人，参加英语竞赛的有15人；同时参加数学和作文的有9人，参加数学和英语的有9人，参加作文和英语的有8人，三项都参加的有2人。三项竞赛都不参加的有多少人？","options":["17","21","26","52"],"answer":0,"explanation":"至少参加一项的有29+15+15−9−9−8+2=35人，都不参加的有52−35=17人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40487","module":"shuliang","prompt":"彩旗按“红、黄、蓝”的顺序循环排列，第76面彩旗是什么颜色？","options":["蓝","黄","红","绿"],"answer":2,"explanation":"周期为3，76÷3=25余1，第76面旗对应周期中的第1个，即“红”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40488","module":"shuliang","prompt":"某商品进价200元，售价360元。该商品的利润率是多少？","options":["75%","83%","80%","160%"],"answer":2,"explanation":"利润=360−200=160元，利润率=160÷200×100%=80%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40489","module":"shuliang","prompt":"5个正整数之和为43（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["40","43","38","39"],"answer":3,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=43−4×1=39。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40490","module":"shuliang","prompt":"某商品进价每件50元，售价每件80元时每天可卖240件。售价每提高1元，每天少卖5件。要使每天利润最大，售价应定为每件多少元？","options":["88","90","89","80"],"answer":2,"explanation":"设售价提高k元，每天利润=(30+k)×(240−5k)，是关于k的二次函数，当k=9时最大，此时售价=80+9=89元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40491","module":"shuliang","prompt":"甲数是乙数的2倍，两数之和是54。乙数是多少？","options":["18","36","26","17"],"answer":0,"explanation":"乙数为1份，甲数为2份，共3份；乙数=54÷3=18。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40492","module":"shuliang","prompt":"张三、李四两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地38千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地48千米处。问A、B两地相距多少千米？","options":["81","105","67","114"],"answer":0,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且张三行38千米，故第二次相遇时张三共行114千米。114大于一个全程而小于两个全程，说明张三已从B地折返，其位置距A地为2S−114（S为全程）。由2S−114=48，解得S=81千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40493","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是45立方分米。圆锥的体积是多少立方分米？","options":["45","15","22","90"],"answer":1,"explanation":"等底等高的圆锥体积是圆柱的1/3，即45÷3=15立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40494","module":"shuliang","prompt":"一项工程，张师傅先做18天、李师傅再做14天恰好完成；若李师傅先做18天、张师傅再做14天也恰好完成。两人合作，需要多少天完成？","options":["32","16","4","17"],"answer":1,"explanation":"设张师傅每天完成x、李师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=32÷2=16天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40495","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才10岁。”乙对甲说：“当我到你这么大时，你就16岁了。”甲今年多少岁？","options":["16","12","15","14"],"answer":3,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙10岁，即乙现在为x+d；乙到甲现在这么大时甲16岁，即甲现在为y−d。由y−d−(x+d)=d得d=(16−10)÷3=2，甲今年=16−2=14岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40496","module":"shuliang","prompt":"快车、慢车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地57千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地39千米处。问A、B两地相距多少千米？","options":["171","130","90","105"],"answer":3,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且快车行57千米，故第二次相遇时快车共行171千米。171大于一个全程而小于两个全程，说明快车已从B地折返，其位置距A地为2S−171（S为全程）。由2S−171=39，解得S=105千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40497","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有43人，参加数学兴趣小组的有24人，两个小组都参加的有16人。两个小组至少参加一个的共有多少人？","options":["83","67","51","19"],"answer":2,"explanation":"都参加的16人被算了两次，需减去一次，故至少参加一个的人数=43+24−16=51人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40498","module":"shuliang","prompt":"甲数与乙数之比为4:2，乙数与丙数之比为2:2。甲数是丙数的多少倍？","options":["9/4","1/2","2","3"],"answer":2,"explanation":"甲:丙=4×2:2×2=8:4，甲是丙的2倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40499","module":"shuliang","prompt":"轿车和面包车分别从相距309千米的两地同时出发，相向而行。轿车每小时行57千米，面包车每小时行46千米，经过多少小时两车相遇？","options":["3","5","2","4"],"answer":0,"explanation":"两车速度之和为57+46=103千米/小时，相遇时间=309÷103=3小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40500","module":"shuliang","prompt":"今年父子二人年龄之和是102岁，父亲年龄是儿子年龄的2倍。父亲今年多少岁？","options":["34","68","74","65"],"answer":1,"explanation":"儿子年龄为1份，父亲为2份，共3份；儿子=102÷3=34岁，父亲=2×34=68岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40501","module":"shuliang","prompt":"某小组共有9名成员，现从中随机选出5名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["106","126","21","105"],"answer":3,"explanation":"从9人中选5人共C(9,5)=126种；甲、乙都不入选有C(7,5)=21种；故至少一人入选共126−21=105种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40502","module":"shuliang","prompt":"A接水需要11分钟，B接水需要12分钟，C接水需要3分钟，D接水需要9分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["35","77","71","38"],"answer":3,"explanation":"让用时短的人先接水可使总等待时间最短。按3、9、11、12的顺序，总等待=3×3+9×2+11×1+12×0=38分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40503","module":"shuliang","prompt":"一项工程，张师傅先做17天、李师傅再做11天恰好完成；若李师傅先做17天、张师傅再做11天也恰好完成。两人合作，需要多少天完成？","options":["14","28","6","15"],"answer":0,"explanation":"设张师傅每天完成x、李师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=28÷2=14天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40504","module":"shuliang","prompt":"甲数是乙数的5倍，两数之和是288。乙数是多少？","options":["48","240","51","44"],"answer":0,"explanation":"乙数为1份，甲数为5份，共6份；乙数=288÷6=48。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40505","module":"shuliang","prompt":"数列{aₙ}满足a₁=3，aₙ₊₁=2aₙ+1，则a5等于多少？","options":["60","66","63","64"],"answer":2,"explanation":"变形得aₙ₊₁+1=2(aₙ+1)，故aₙ+1=(3+1)×2^(n−1)，a5=(3+1)×16−1=63。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40506","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供16头牛吃21天，或供22头牛吃7天。若放34头牛，可以吃多少天？","options":["10","5","2","3"],"answer":3,"explanation":"每天长草量=(22×7−16×21)÷(7−21)=13份，原有草量=16×21−13×21=63份；34头牛每天净消耗34−13=21份，可吃63÷21=3天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40507","module":"shuliang","prompt":"某商场促销“满300减60”，小明购买了标价600元的商品（满足优惠条件）。实际付款相当于打几折？","options":["2折","9折","7折","8折"],"answer":3,"explanation":"优惠后实付600−2×60=480元，480÷600=4/5，相当于打8折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40508","module":"shuliang","prompt":"甲种卡车每次可运8吨货物，耗油9升；乙种卡车每次可运2吨货物，耗油7升。现要运送72吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["79","86","81","252"],"answer":2,"explanation":"甲车每吨耗油9/8升，乙车每吨耗油7/2升，甲车更省。尽量用甲车：9车次运72吨，余0吨用乙车0次，共耗油81升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40509","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有26人，参加数学兴趣小组的有26人，两个小组都参加的有9人。两个小组至少参加一个的共有多少人？","options":["52","43","61","0"],"answer":1,"explanation":"都参加的9人被算了两次，需减去一次，故至少参加一个的人数=26+26−9=43人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40510","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有21人，参加羽毛球赛的有28人，参加乒乓球赛的有25人；同时参加篮球和羽毛球的有9人，参加篮球和乒乓球的有6人，参加羽毛球和乒乓球的有7人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["42","47","38","56"],"answer":0,"explanation":"只参加篮球=21−9−6+4=10人；同理只参加羽毛球=16人，只参加乒乓球=16人；合计10+16+16=42人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40511","module":"shuliang","prompt":"5个正整数之和为69（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["13","16","14","15"],"answer":2,"explanation":"最大数最小时各数尽量平均，69÷5=13余4，故最大数至少为14（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40512","module":"shuliang","prompt":"今天是星期六，再过14天是星期几？","options":["星期日","星期六","星期五","星期二"],"answer":1,"explanation":"14÷7=2余0，星期六往后推0天是星期六。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40513","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供12头牛吃20天，或供19头牛吃10天。若放40头牛，可以吃多少天？","options":["4","6","3","7"],"answer":0,"explanation":"每天长草量=(19×10−12×20)÷(10−20)=5份，原有草量=12×20−5×20=140份；40头牛每天净消耗40−5=35份，可吃140÷35=4天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40514","module":"shuliang","prompt":"6个正整数之和为56（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["56","51","55","50"],"answer":1,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=56−5×1=51。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40515","module":"shuliang","prompt":"一个长方形的长为29米，宽为13米，它的周长是多少米？","options":["42","377","84","86"],"answer":2,"explanation":"长方形周长=2×（长+宽）=2×(29+13)=84米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40516","module":"shuliang","prompt":"某商品按进价加价30%定价，然后按6折出售，仍可获利。该商品的利润率是多少？","options":["-18%","18%","-22%","-13%"],"answer":2,"explanation":"设进价为100，售价=100×(1+30%)×6/10=78，利润率=78−100=-22%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40517","module":"shuliang","prompt":"5个正整数之和为60（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["56","60","55","53"],"answer":0,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=60−4×1=56。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40518","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才14岁。”乙对甲说：“当我到你这么大时，你就47岁了。”甲今年多少岁？","options":["34","25","37","36"],"answer":3,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙14岁，即乙现在为x+d；乙到甲现在这么大时甲47岁，即甲现在为y−d。由y−d−(x+d)=d得d=(47−14)÷3=11，甲今年=47−11=36岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40519","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供18头牛吃20天，或供34头牛吃10天。若放34头牛，可以吃多少天？","options":["9","11","10","12"],"answer":2,"explanation":"每天长草量=(34×10−18×20)÷(10−20)=2份，原有草量=18×20−2×20=320份；34头牛每天净消耗34−2=32份，可吃320÷32=10天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40520","module":"shuliang","prompt":"张三、李四两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地44千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地102千米处。问A、B两地相距多少千米？","options":["135","117","99","132"],"answer":1,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且张三行44千米，故第二次相遇时张三共行132千米。132大于一个全程而小于两个全程，说明张三已从B地折返，其位置距A地为2S−132（S为全程）。由2S−132=102，解得S=117千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40521","module":"shuliang","prompt":"快车和慢车分别从相距515千米的两地同时出发，相向而行。快车每小时行69千米，慢车每小时行34千米，经过多少小时两车相遇？","options":["7","5","4","6"],"answer":1,"explanation":"两车速度之和为69+34=103千米/小时，相遇时间=515÷103=5小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40522","module":"shuliang","prompt":"已知等差数列的前10项和为215，前20项和为730，则该数列的公差是多少？","options":["3","4","2","1"],"answer":0,"explanation":"S20−2×S10=(730)−2×(215)=300=100d（第11到20项之和比前10项之和多100d），故d=3。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40523","module":"shuliang","prompt":"甲种卡车每次可运6吨货物，耗油9升；乙种卡车每次可运3吨货物，耗油7升。现要运送48吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["67","76","72","112"],"answer":2,"explanation":"甲车每吨耗油9/6升，乙车每吨耗油7/3升，甲车更省。尽量用甲车：8车次运48吨，余0吨用乙车0次，共耗油72升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40524","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有23人，参加物理组的有26人，参加化学组的有37人；同时参加数学和物理的有8人，参加数学和化学的有5人，参加物理和化学的有9人，三个组都参加的有5人。三个组至少参加一个的共有多少人？","options":["69","86","71","66"],"answer":0,"explanation":"由三集合容斥公式：至少参加一个=23+26+37−8−5−9+5=69人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40525","module":"shuliang","prompt":"轿车在面包车后方28千米处，两人同时同向出发。轿车每小时行58千米，面包车每小时行30千米，经过多少小时轿车追上面包车？","options":["58","3","28","1"],"answer":3,"explanation":"每小时轿车比面包车多行58-30=28千米，追及时间=28÷28=1小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40526","module":"shuliang","prompt":"A接水需要6分钟，B接水需要7分钟，C接水需要8分钟，D接水需要10分钟，E接水需要5分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["102","60","94","36"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按5、6、7、8、10的顺序，总等待=5×4+6×3+7×2+8×1+10×0=60分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40527","module":"shuliang","prompt":"在一个边长为10厘米的正方形纸片内，剪一个最大的圆（圆的直径等于正方形边长，π取3.14）。剩下的纸片面积是多少平方厘米？","options":["17","100","30","22"],"answer":3,"explanation":"正方形面积=100平方厘米，最大圆半径为5厘米，圆面积=3.14×5²=78平方厘米，剩余=100−78=22平方厘米。","exam":"通用基础","__sub":"几何问题","diff":3},{"id":"sl-40528","module":"shuliang","prompt":"某商品进价每件30元，售价每件70元时每天可卖168件。售价每提高1元，每天少卖4件。要使每天利润最大，售价应定为每件多少元？","options":["70","72","68","71"],"answer":3,"explanation":"设售价提高k元，每天利润=(40+k)×(168−4k)，是关于k的二次函数，当k=1时最大，此时售价=70+1=71元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40529","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有33人，参加羽毛球赛的有21人，参加乒乓球赛的有25人；同时参加篮球和羽毛球的有12人，参加篮球和乒乓球的有12人，参加羽毛球和乒乓球的有11人，三项都参加的有6人。只参加其中一项比赛的有多少人？","options":["25","32","27","50"],"answer":2,"explanation":"只参加篮球=33−12−12+6=15人；同理只参加羽毛球=4人，只参加乒乓球=8人；合计15+4+8=27人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40530","module":"shuliang","prompt":"已知等比数列的首项为4，公比为2，则它的第5项是多少？","options":["128","64","32","66"],"answer":1,"explanation":"等比数列第n项=首项×公比^(n−1)=4×2^(5-1)=64。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40531","module":"shuliang","prompt":"张三和李四的速度比为8:3，两人同时同地同向出发赛跑，当张三到达终点时，李四距终点还有30米。赛道全程是多少米？","options":["48","65","10","240"],"answer":0,"explanation":"同一时间内路程比等于速度比，李四走了全程的3/8，还差全程的5/8=30米，故全程=30×8÷5=48米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40532","module":"shuliang","prompt":"某商品按进价加价40%定价，然后按9折出售，仍可获利。该商品的利润率是多少？","options":["26%","36%","34%","23%"],"answer":0,"explanation":"设进价为100，售价=100×(1+40%)×9/10=126，利润率=126−100=26%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40533","module":"shuliang","prompt":"抽屉里有8种不同颜色的手套（每种数量都足够多），至少取出多少只才能保证有一副颜色相同的手套？","options":["10","8","9","16"],"answer":2,"explanation":"考虑最不利情形：每种颜色各取1只共8只仍无同色一副，再取1只必与某只同色，故至少取9只。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40534","module":"shuliang","prompt":"在一个边长为30厘米的正方形纸片内，剪一个最大的圆（圆的直径等于正方形边长，π取3.14）。剩下的纸片面积是多少平方厘米？","options":["186","900","197","194"],"answer":3,"explanation":"正方形面积=900平方厘米，最大圆半径为15厘米，圆面积=3.14×15²=706平方厘米，剩余=900−706=194平方厘米。","exam":"通用基础","__sub":"几何问题","diff":3},{"id":"sl-40535","module":"shuliang","prompt":"袋中有4个红球和6个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["3/5","2/5","1","1/2"],"answer":1,"explanation":"共有10个球，红球4个，取到红球的概率为4/10=2/5。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40536","module":"shuliang","prompt":"某班共有49人，参加数学竞赛的有23人，参加作文竞赛的有23人，参加英语竞赛的有16人；同时参加数学和作文的有4人，参加数学和英语的有8人，参加作文和英语的有6人，三项都参加的有3人。三项竞赛都不参加的有多少人？","options":["2","5","18","49"],"answer":0,"explanation":"至少参加一项的有23+23+16−4−8−6+3=47人，都不参加的有49−47=2人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40537","module":"shuliang","prompt":"彩旗按“红、白、黑、蓝”的顺序循环排列，第48面彩旗是什么颜色？","options":["红","蓝","黑","白"],"answer":1,"explanation":"周期为4，48÷4=12余0，第48面旗对应周期中的第4个，即“蓝”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40538","module":"shuliang","prompt":"两个数的和是114，差是26。这两个数中较大的数是多少？","options":["31","83","70","114"],"answer":2,"explanation":"小数=（和−差）÷2=44，大数=（和+差）÷2=70。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40539","module":"shuliang","prompt":"甲数是乙数的5倍，两数之和是348。乙数是多少？","options":["61","290","58","57"],"answer":2,"explanation":"乙数为1份，甲数为5份，共6份；乙数=348÷6=58。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40540","module":"shuliang","prompt":"6个正整数之和为52（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["51","52","47","46"],"answer":2,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=52−5×1=47。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40541","module":"shuliang","prompt":"甲种卡车每次可运8吨货物，耗油16升；乙种卡车每次可运2吨货物，耗油6升。现要运送96吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["288","196","187","192"],"answer":3,"explanation":"甲车每吨耗油16/8升，乙车每吨耗油6/2升，甲车更省。尽量用甲车：12车次运96吨，余0吨用乙车0次，共耗油192升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40542","module":"shuliang","prompt":"两个正数的和为36，要使它们的乘积最大，则最大的乘积是多少？","options":["329","36","324","322"],"answer":2,"explanation":"两数和一定时，两数相等时乘积最大，均为36÷2=18，最大乘积=18×18=324。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40543","module":"shuliang","prompt":"6个正整数之和为38（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["33","38","36","32"],"answer":0,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=38−5×1=33。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40544","module":"shuliang","prompt":"某商场促销“满200减40”，小明购买了标价600元的商品（满足优惠条件）。实际付款相当于打几折？","options":["7折","9折","8折","2折"],"answer":2,"explanation":"优惠后实付600−3×40=480元，480÷600=4/5，相当于打8折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40545","module":"shuliang","prompt":"袋中有4个红球和8个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["1/2","2/3","1","1/3"],"answer":3,"explanation":"共有12个球，红球4个，取到红球的概率为4/12=1/3。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40546","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才14岁。”乙对甲说：“当我到你这么大时，你就32岁了。”甲今年多少岁？","options":["26","20","27","25"],"answer":0,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙14岁，即乙现在为x+d；乙到甲现在这么大时甲32岁，即甲现在为y−d。由y−d−(x+d)=d得d=(32−14)÷3=6，甲今年=32−6=26岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40547","module":"shuliang","prompt":"一列火车长299米，以每秒14米的速度通过一座长1400米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["122","21","100","121"],"answer":3,"explanation":"火车完全过桥需行驶299+1400=1699米，时间=1699÷14=121秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40548","module":"shuliang","prompt":"一个圆的半径为50厘米（π取3.14），它的面积是多少平方厘米？","options":["7813","314","7870","7850"],"answer":3,"explanation":"圆的面积=πr²=3.14×50×50=7850平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40549","module":"shuliang","prompt":"甲和乙的速度比为7:3，两人同时同地同向出发赛跑，当甲到达终点时，乙距终点还有60米。赛道全程是多少米？","options":["61","131","105","420"],"answer":2,"explanation":"同一时间内路程比等于速度比，乙走了全程的3/7，还差全程的4/7=60米，故全程=60×7÷4=105米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40550","module":"shuliang","prompt":"客车和货车的速度比为8:4，两人同时同地同向出发赛跑，当客车到达终点时，货车距终点还有30米。赛道全程是多少米？","options":["31","79","60","240"],"answer":2,"explanation":"同一时间内路程比等于速度比，货车走了全程的4/8，还差全程的4/8=30米，故全程=30×8÷4=60米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40551","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才16岁。”乙对甲说：“当我到你这么大时，你就43岁了。”甲今年多少岁？","options":["36","25","34","32"],"answer":2,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙16岁，即乙现在为x+d；乙到甲现在这么大时甲43岁，即甲现在为y−d。由y−d−(x+d)=d得d=(43−16)÷3=9，甲今年=43−9=34岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40552","module":"shuliang","prompt":"某商品进价600元，售价1020元。该商品的利润率是多少？","options":["64%","80%","70%","140%"],"answer":2,"explanation":"利润=1020−600=420元，利润率=420÷600×100%=70%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40553","module":"shuliang","prompt":"数列{aₙ}满足a₁=2，aₙ₊₁=2aₙ+1，则a7等于多少？","options":["192","194","190","191"],"answer":3,"explanation":"变形得aₙ₊₁+1=2(aₙ+1)，故aₙ+1=(2+1)×2^(n−1)，a7=(2+1)×64−1=191。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40554","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行28千米，按原路返回时每小时行70千米。该车往返全程的平均速度是多少千米/小时？","options":["40","49","41","39"],"answer":0,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/28+1/70)=2×28×70÷(28+70)=40千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40555","module":"shuliang","prompt":"抽屉里有3种不同颜色的手套（每种数量都足够多），至少取出多少只才能保证有一副颜色相同的手套？","options":["6","3","4","7"],"answer":2,"explanation":"考虑最不利情形：每种颜色各取1只共3只仍无同色一副，再取1只必与某只同色，故至少取4只。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40556","module":"shuliang","prompt":"抽屉里有6种不同颜色的手套（每种数量都足够多），至少取出多少只才能保证有一副颜色相同的手套？","options":["7","6","8","12"],"answer":0,"explanation":"考虑最不利情形：每种颜色各取1只共6只仍无同色一副，再取1只必与某只同色，故至少取7只。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40557","module":"shuliang","prompt":"某商品进价每件20元，售价每件50元时每天可卖180件。售价每提高1元，每天少卖3件。要使每天利润最大，售价应定为每件多少元？","options":["65","67","62","50"],"answer":0,"explanation":"设售价提高k元，每天利润=(30+k)×(180−3k)，是关于k的二次函数，当k=15时最大，此时售价=50+15=65元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40558","module":"shuliang","prompt":"今年甲的年龄是乙的3倍，9年后甲的年龄是乙的2倍。乙今年多少岁？","options":["81","10","7","9"],"answer":3,"explanation":"设乙今年x岁，则甲为3x岁；9年后：3x+9=2(x+9)，解得x=9岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40559","module":"shuliang","prompt":"5个正整数之和为59（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["55","59","56","54"],"answer":0,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=59−4×1=55。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40560","module":"shuliang","prompt":"已知等差数列的前10项和为245，前20项和为990，则该数列的公差是多少？","options":["5","7","4","1"],"answer":0,"explanation":"S20−2×S10=(990)−2×(245)=500=100d（第11到20项之和比前10项之和多100d），故d=5。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40561","module":"shuliang","prompt":"同时掷两枚均匀的骰子，点数之和为5的概率是多少？","options":["1/6","1/12","5/36","1/9"],"answer":3,"explanation":"两枚骰子共6×6=36种等可能结果，点数之和为5的有4种，概率为4/36=1/9。","exam":"通用基础","__sub":"概率问题","diff":2},{"id":"sl-40562","module":"shuliang","prompt":"在一个边长为16厘米的正方形纸片内，剪一个最大的圆（圆的直径等于正方形边长，π取3.14）。剩下的纸片面积是多少平方厘米？","options":["52","256","62","56"],"answer":3,"explanation":"正方形面积=256平方厘米，最大圆半径为8厘米，圆面积=3.14×8²=200平方厘米，剩余=256−200=56平方厘米。","exam":"通用基础","__sub":"几何问题","diff":3},{"id":"sl-40563","module":"shuliang","prompt":"一个长方体的长、宽、高分别为9厘米、12厘米、8厘米，它的体积是多少立方厘米？","options":["864","552","29","108"],"answer":0,"explanation":"长方体体积=长×宽×高=9×12×8=864立方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40564","module":"shuliang","prompt":"某单位组织128人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["1090","1257","1200","1400"],"answer":2,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为1200元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40565","module":"shuliang","prompt":"甲接水需要12分钟，乙接水需要9分钟，丙接水需要4分钟，丁接水需要5分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["63","31","59","30"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按4、5、9、12的顺序，总等待=4×3+5×2+9×1+12×0=31分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40566","module":"shuliang","prompt":"一项工程，老周单独做需要15天完成，老吴单独做需要10天完成。两人（队）合作，需要多少天完成？","options":["13","25","5","6"],"answer":3,"explanation":"把工程总量看作1，两人效率之和为1/15+1/10=(15+10)/150，合作需要150÷(15+10)=6天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40567","module":"shuliang","prompt":"甲和乙的速度比为6:4，两人同时同地同向出发赛跑，当甲到达终点时，乙距终点还有30米。赛道全程是多少米？","options":["90","120","78","180"],"answer":0,"explanation":"同一时间内路程比等于速度比，乙走了全程的4/6，还差全程的2/6=30米，故全程=30×6÷2=90米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40568","module":"shuliang","prompt":"一项工程，张师傅单独做需要3天完成，李师傅单独做需要6天完成。两人（队）合作，需要多少天完成？","options":["2","9","3","5"],"answer":0,"explanation":"把工程总量看作1，两人效率之和为1/3+1/6=(3+6)/18，合作需要18÷(3+6)=2天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40569","module":"shuliang","prompt":"一项工程，一队单独做需要24天完成，二队单独做需要40天完成。两人（队）合作，需要多少天完成？","options":["15","64","16","32"],"answer":0,"explanation":"把工程总量看作1，两人效率之和为1/24+1/40=(24+40)/960，合作需要960÷(24+40)=15天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40570","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需72小时，逆流需108小时，两码头相距2592千米。该轮船在静水中的速度是多少千米/小时？","options":["29","6","36","30"],"answer":3,"explanation":"顺流速度=2592÷72=36千米/小时，逆流速度=2592÷108=24千米/小时；静水速度=(36+24)÷2=30千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40571","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是27立方分米。圆锥的体积是多少立方分米？","options":["13","27","9","54"],"answer":2,"explanation":"等底等高的圆锥体积是圆柱的1/3，即27÷3=9立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40572","module":"shuliang","prompt":"某淘汰赛共有28支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["14","28","27","29"],"answer":2,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰27支，故共需27场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40573","module":"shuliang","prompt":"某商场促销“满300减30”，小明购买了标价1200元的商品（满足优惠条件）。实际付款相当于打几折？","options":["9折","10折","8折","1折"],"answer":0,"explanation":"优惠后实付1200−4×30=1080元，1080÷1200=9/10，相当于打9折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40574","module":"shuliang","prompt":"抽屉里有7种不同颜色的手套（每种数量都足够多），至少取出多少只才能保证有一副颜色相同的手套？","options":["7","8","9","14"],"answer":1,"explanation":"考虑最不利情形：每种颜色各取1只共7只仍无同色一副，再取1只必与某只同色，故至少取8只。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40575","module":"shuliang","prompt":"已知等差数列的首项为2，公差为4，则它的第20项是多少？","options":["82","78","74","79"],"answer":1,"explanation":"等差数列第n项=首项+(n−1)×公差=2+(20-1)×4=78。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40576","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行54千米，按原路返回时每小时行27千米。该车往返全程的平均速度是多少千米/小时？","options":["36","40","37","35"],"answer":0,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/54+1/27)=2×54×27÷(54+27)=36千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40577","module":"shuliang","prompt":"已知等差数列的首项为10，公差为4，则它的前18项之和是多少？","options":["1404","792","797","787"],"answer":1,"explanation":"第18项=10+(18-1)×4=78，前18项和=n×(首项+末项)÷2=18×(10+78)÷2=792。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40578","module":"shuliang","prompt":"轿车、面包车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地51千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地51千米处。问A、B两地相距多少千米？","options":["125","102","90","153"],"answer":1,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且轿车行51千米，故第二次相遇时轿车共行153千米。153大于一个全程而小于两个全程，说明轿车已从B地折返，其位置距A地为2S−153（S为全程）。由2S−153=51，解得S=102千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40579","module":"shuliang","prompt":"一个正方形的边长扩大到原来的4倍，它的面积扩大到原来的多少倍？","options":["16","4","8","20"],"answer":0,"explanation":"边长扩大4倍，面积扩大4×4=16倍。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40580","module":"shuliang","prompt":"已知等比数列的首项为3，公比为3，则它的第6项是多少？","options":["732","2187","243","729"],"answer":3,"explanation":"等比数列第n项=首项×公比^(n−1)=3×3^(6-1)=729。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40581","module":"shuliang","prompt":"在一个边长为24厘米的正方形纸片内，剪一个最大的圆（圆的直径等于正方形边长，π取3.14）。剩下的纸片面积是多少平方厘米？","options":["576","124","134","121"],"answer":1,"explanation":"正方形面积=576平方厘米，最大圆半径为12厘米，圆面积=3.14×12²=452平方厘米，剩余=576−452=124平方厘米。","exam":"通用基础","__sub":"几何问题","diff":3},{"id":"sl-40582","module":"shuliang","prompt":"同一时刻，一根4米高的标杆在阳光下的影长为5米，附近一棵大树的影长为20米。这棵大树的高度是多少米？","options":["16","24","17","20"],"answer":0,"explanation":"同一时刻物高与影长成正比，树高=4×20÷5=16米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40583","module":"shuliang","prompt":"某商品进价每件40元，售价每件60元时每天可卖348件。售价每提高1元，每天少卖6件。要使每天利润最大，售价应定为每件多少元？","options":["60","82","77","79"],"answer":3,"explanation":"设售价提高k元，每天利润=(20+k)×(348−6k)，是关于k的二次函数，当k=19时最大，此时售价=60+19=79元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40584","module":"shuliang","prompt":"甲接水需要10分钟，乙接水需要2分钟，丙接水需要6分钟，丁接水需要7分钟，戊接水需要5分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["70","78","42","30"],"answer":2,"explanation":"让用时短的人先接水可使总等待时间最短。按2、5、6、7、10的顺序，总等待=2×4+5×3+6×2+7×1+10×0=42分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40585","module":"shuliang","prompt":"一项工程，王师傅单独做需要12天完成，赵师傅单独做需要24天完成。两人（队）合作，需要多少天完成？","options":["12","36","8","18"],"answer":2,"explanation":"把工程总量看作1，两人效率之和为1/12+1/24=(12+24)/288，合作需要288÷(12+24)=8天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40586","module":"shuliang","prompt":"一个长方形的长为24米，宽为5米，它的周长是多少米？","options":["120","58","29","60"],"answer":1,"explanation":"长方形周长=2×（长+宽）=2×(24+5)=58米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40587","module":"shuliang","prompt":"一项工程，一队先做19天、二队再做5天恰好完成；若二队先做19天、一队再做5天也恰好完成。两人合作，需要多少天完成？","options":["24","12","14","13"],"answer":1,"explanation":"设一队每天完成x、二队每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=24÷2=12天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40588","module":"shuliang","prompt":"甲在乙后方9千米处，两人同时同向出发。甲每小时行82千米，乙每小时行73千米，经过多少小时甲追上乙？","options":["82","3","9","1"],"answer":3,"explanation":"每小时甲比乙多行82-73=9千米，追及时间=9÷9=1小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40589","module":"shuliang","prompt":"彩旗按“甲、乙、丙、丁、戊”的顺序循环排列，第27面彩旗是什么颜色？","options":["丁","丙","甲","乙"],"answer":3,"explanation":"周期为5，27÷5=5余2，第27面旗对应周期中的第2个，即“乙”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40590","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行30千米，按原路返回时每小时行60千米。该车往返全程的平均速度是多少千米/小时？","options":["40","45","43","39"],"answer":0,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/30+1/60)=2×30×60÷(30+60)=40千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40591","module":"shuliang","prompt":"同时掷两枚均匀的骰子，点数之和为9的概率是多少？","options":["1/12","1/9","5/36","1/6"],"answer":1,"explanation":"两枚骰子共6×6=36种等可能结果，点数之和为9的有4种，概率为4/36=1/9。","exam":"通用基础","__sub":"概率问题","diff":2},{"id":"sl-40592","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供18头牛吃23天，或供32头牛吃9天。若放32头牛，可以吃多少天？","options":["13","10","8","9"],"answer":3,"explanation":"每天长草量=(32×9−18×23)÷(9−23)=9份，原有草量=18×23−9×23=207份；32头牛每天净消耗32−9=23份，可吃207÷23=9天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40593","module":"shuliang","prompt":"6个正整数之和为37（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["37","32","34","31"],"answer":1,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=37−5×1=32。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40594","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有26人，参加羽毛球赛的有35人，参加乒乓球赛的有29人；同时参加篮球和羽毛球的有6人，参加篮球和乒乓球的有12人，参加羽毛球和乒乓球的有11人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["43","47","44","65"],"answer":2,"explanation":"只参加篮球=26−6−12+4=12人；同理只参加羽毛球=22人，只参加乒乓球=10人；合计12+22+10=44人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40595","module":"shuliang","prompt":"6个正整数之和为53（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["53","48","50","47"],"answer":1,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=53−5×1=48。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40596","module":"shuliang","prompt":"某商场促销“满100减20”，小明购买了标价500元的商品（满足优惠条件）。实际付款相当于打几折？","options":["7折","9折","8折","2折"],"answer":2,"explanation":"优惠后实付500−5×20=400元，400÷500=4/5，相当于打8折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40597","module":"shuliang","prompt":"某单位组织67人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["680","752","578","800"],"answer":0,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为680元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40598","module":"shuliang","prompt":"4个正整数之和为36（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["7","10","9","11"],"answer":2,"explanation":"最大数最小时各数尽量平均，36÷4=9余0，故最大数至少为9（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40599","module":"shuliang","prompt":"轿车和面包车分别从相距560千米的两地同时出发，相向而行。轿车每小时行55千米，面包车每小时行57千米，经过多少小时两车相遇？","options":["4","7","5","6"],"answer":2,"explanation":"两车速度之和为55+57=112千米/小时，相遇时间=560÷112=5小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40600","module":"shuliang","prompt":"两个数的和是212，差是40。这两个数中较大的数是多少？","options":["66","146","126","212"],"answer":2,"explanation":"小数=（和−差）÷2=86，大数=（和+差）÷2=126。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40601","module":"shuliang","prompt":"数列{aₙ}满足a₁=1，aₙ₊₁=2aₙ+1，则a5等于多少？","options":["31","36","28","32"],"answer":0,"explanation":"变形得aₙ₊₁+1=2(aₙ+1)，故aₙ+1=(1+1)×2^(n−1)，a5=(1+1)×16−1=31。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40602","module":"shuliang","prompt":"4个正整数之和为59（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["57","59","56","55"],"answer":2,"explanation":"要使最大的数最大，其余3个数都取最小值1，故最大数=59−3×1=56。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40603","module":"shuliang","prompt":"今天是星期四，再过137天是星期几？","options":["星期二","星期一","星期日","星期三"],"answer":1,"explanation":"137÷7=19余4，星期四往后推4天是星期一。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40604","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有31人，参加数学兴趣小组的有27人，两个小组都参加的有19人。两个小组至少参加一个的共有多少人？","options":["4","58","77","39"],"answer":3,"explanation":"都参加的19人被算了两次，需减去一次，故至少参加一个的人数=31+27−19=39人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40605","module":"shuliang","prompt":"同一时刻，一根5米高的标杆在阳光下的影长为8米，附近一棵大树的影长为40米。这棵大树的高度是多少米？","options":["25","45","26","40"],"answer":0,"explanation":"同一时刻物高与影长成正比，树高=5×40÷8=25米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40606","module":"shuliang","prompt":"一项工程，一队单独做需要6天完成，二队单独做需要12天完成。两人（队）合作，需要多少天完成？","options":["9","18","6","4"],"answer":3,"explanation":"把工程总量看作1，两人效率之和为1/6+1/12=(6+12)/72，合作需要72÷(6+12)=4天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40607","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有26人，参加羽毛球赛的有22人，参加乒乓球赛的有35人；同时参加篮球和羽毛球的有10人，参加篮球和乒乓球的有12人，参加羽毛球和乒乓球的有11人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["31","29","26","54"],"answer":1,"explanation":"只参加篮球=26−10−12+4=8人；同理只参加羽毛球=5人，只参加乒乓球=16人；合计8+5+16=29人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40608","module":"shuliang","prompt":"彩旗按“甲、乙、丙、丁、戊”的顺序循环排列，第84面彩旗是什么颜色？","options":["丁","戊","丙","甲"],"answer":0,"explanation":"周期为5，84÷5=16余4，第84面旗对应周期中的第4个，即“丁”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40609","module":"shuliang","prompt":"六本不同的书分给甲、乙、丙三人，每人恰好两本，共有多少种不同的分法？","options":["45","180","30","90"],"answer":3,"explanation":"甲先选C(6,2)=15种，乙再选C(4,2)=6种，丙取剩下的C(2,2)=1种，共15×6×1=90种。","exam":"通用基础","__sub":"排列组合","diff":3},{"id":"sl-40610","module":"shuliang","prompt":"今年甲的年龄是乙的4倍，13年后甲的年龄是乙的3倍。乙今年多少岁？","options":["26","29","25","13"],"answer":0,"explanation":"设乙今年x岁，则甲为4x岁；13年后：4x+13=3(x+13)，解得x=26岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40611","module":"shuliang","prompt":"甲在乙后方75千米处，两人同时同向出发。甲每小时行57千米，乙每小时行42千米，经过多少小时甲追上乙？","options":["5","6","7","75"],"answer":0,"explanation":"每小时甲比乙多行57-42=15千米，追及时间=75÷15=5小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40612","module":"shuliang","prompt":"4个正整数之和为40（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["36","40","37","35"],"answer":2,"explanation":"要使最大的数最大，其余3个数都取最小值1，故最大数=40−3×1=37。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40613","module":"shuliang","prompt":"一只手表每小时比标准时间快5秒。若以标准时间为准，这只手表一昼夜（24小时）共快多少分钟？","options":["6","4","2","24"],"answer":2,"explanation":"每小时快5秒，一昼夜24小时共快24×5=120秒=2分钟。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40614","module":"shuliang","prompt":"数列{aₙ}满足a₁=3，aₙ₊₁=2aₙ+1，则a6等于多少？","options":["127","129","124","128"],"answer":0,"explanation":"变形得aₙ₊₁+1=2(aₙ+1)，故aₙ+1=(3+1)×2^(n−1)，a6=(3+1)×32−1=127。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40615","module":"shuliang","prompt":"甲种卡车每次可运8吨货物，耗油10升；乙种卡车每次可运3吨货物，耗油4升。现要运送88吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["110","114","105","116"],"answer":0,"explanation":"甲车每吨耗油10/8升，乙车每吨耗油4/3升，甲车更省。尽量用甲车：11车次运88吨，余0吨用乙车0次，共耗油110升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40616","module":"shuliang","prompt":"两个数的和是180，差是32。这两个数中较大的数是多少？","options":["106","122","58","180"],"answer":0,"explanation":"小数=（和−差）÷2=74，大数=（和+差）÷2=106。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40617","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供19头牛吃20天，或供33头牛吃10天。若放40头牛，可以吃多少天？","options":["10","9","7","8"],"answer":3,"explanation":"每天长草量=(33×10−19×20)÷(10−20)=5份，原有草量=19×20−5×20=280份；40头牛每天净消耗40−5=35份，可吃280÷35=8天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40618","module":"shuliang","prompt":"今年父子二人年龄之和是135岁，父亲年龄是儿子年龄的4倍。父亲今年多少岁？","options":["112","27","108","103"],"answer":2,"explanation":"儿子年龄为1份，父亲为4份，共5份；儿子=135÷5=27岁，父亲=4×27=108岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40619","module":"shuliang","prompt":"今年父子二人年龄之和是155岁，父亲年龄是儿子年龄的4倍。父亲今年多少岁？","options":["31","124","128","121"],"answer":1,"explanation":"儿子年龄为1份，父亲为4份，共5份；儿子=155÷5=31岁，父亲=4×31=124岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40620","module":"shuliang","prompt":"5个正整数之和为51（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["47","51","49","46"],"answer":0,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=51−4×1=47。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40621","module":"shuliang","prompt":"一项工程，张师傅先做7天、李师傅再做17天恰好完成；若李师傅先做7天、张师傅再做17天也恰好完成。两人合作，需要多少天完成？","options":["13","24","10","12"],"answer":3,"explanation":"设张师傅每天完成x、李师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=24÷2=12天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40622","module":"shuliang","prompt":"快车在慢车后方32千米处，两人同时同向出发。快车每小时行86千米，慢车每小时行70千米，经过多少小时快车追上慢车？","options":["86","4","32","2"],"answer":3,"explanation":"每小时快车比慢车多行86-70=16千米，追及时间=32÷16=2小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40623","module":"shuliang","prompt":"一项工程，张师傅先做11天、李师傅再做5天恰好完成；若李师傅先做11天、张师傅再做5天也恰好完成。两人合作，需要多少天完成？","options":["16","8","6","9"],"answer":1,"explanation":"设张师傅每天完成x、李师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=16÷2=8天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40624","module":"shuliang","prompt":"甲数是乙数的4倍，两数之和是210。乙数是多少？","options":["38","168","48","42"],"answer":3,"explanation":"乙数为1份，甲数为4份，共5份；乙数=210÷5=42。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40625","module":"shuliang","prompt":"某商品进价每件20元，售价每件50元时每天可卖200件。售价每提高1元，每天少卖4件。要使每天利润最大，售价应定为每件多少元？","options":["60","62","58","50"],"answer":0,"explanation":"设售价提高k元，每天利润=(30+k)×(200−4k)，是关于k的二次函数，当k=10时最大，此时售价=50+10=60元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40626","module":"shuliang","prompt":"已知等差数列的首项为1，公差为2，则它的前13项之和是多少？","options":["325","169","179","167"],"answer":1,"explanation":"第13项=1+(13-1)×2=25，前13项和=n×(首项+末项)÷2=13×(1+25)÷2=169。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40627","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供16头牛吃18天，或供24头牛吃9天。若放44头牛，可以吃多少天？","options":["5","4","3","7"],"answer":1,"explanation":"每天长草量=(24×9−16×18)÷(9−18)=8份，原有草量=16×18−8×18=144份；44头牛每天净消耗44−8=36份，可吃144÷36=4天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40628","module":"shuliang","prompt":"某淘汰赛共有20支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["10","20","19","21"],"answer":2,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰19支，故共需19场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40629","module":"shuliang","prompt":"时钟9点50分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["10","5","25","175"],"answer":1,"explanation":"时针与12点方向夹角为30×9+0.5×50=295.0度，分针与12点方向夹角为6×50=300度，两针夹角为5度，取小于180度的角为5.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40630","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才18岁。”乙对甲说：“当我到你这么大时，你就42岁了。”甲今年多少岁？","options":["33","26","36","34"],"answer":3,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙18岁，即乙现在为x+d；乙到甲现在这么大时甲42岁，即甲现在为y−d。由y−d−(x+d)=d得d=(42−18)÷3=8，甲今年=42−8=34岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40631","module":"shuliang","prompt":"已知等差数列的前10项和为260，前20项和为920，则该数列的公差是多少？","options":["6","4","3","1"],"answer":1,"explanation":"S20−2×S10=(920)−2×(260)=400=100d（第11到20项之和比前10项之和多100d），故d=4。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40632","module":"shuliang","prompt":"某商品按定价出售每件可赚50元，若按定价的8折出售，每件将亏损40元。该商品的进价是多少元？","options":["90","419","361","400"],"answer":3,"explanation":"设进价为C，定价为C+50；8折售价为8/10×(C+50)=C−40，解得C=400元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40633","module":"shuliang","prompt":"某小组共有8名成员，现从中随机选出5名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["56","50","6","55"],"answer":1,"explanation":"从8人中选5人共C(8,5)=56种；甲、乙都不入选有C(6,5)=6种；故至少一人入选共56−6=50种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40634","module":"shuliang","prompt":"甲种卡车每次可运6吨货物，耗油10升；乙种卡车每次可运3吨货物，耗油7升。现要运送24吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["40","45","34","56"],"answer":0,"explanation":"甲车每吨耗油10/6升，乙车每吨耗油7/3升，甲车更省。尽量用甲车：4车次运24吨，余0吨用乙车0次，共耗油40升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40635","module":"shuliang","prompt":"一项工程，甲先做8天、乙再做6天恰好完成；若乙先做8天、甲再做6天也恰好完成。两人合作，需要多少天完成？","options":["7","14","2","8"],"answer":0,"explanation":"设甲每天完成x、乙每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=14÷2=7天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40636","module":"shuliang","prompt":"数列{aₙ}满足a₁=2，aₙ₊₁=2aₙ+1，则a5等于多少？","options":["48","52","45","47"],"answer":3,"explanation":"变形得aₙ₊₁+1=2(aₙ+1)，故aₙ+1=(2+1)×2^(n−1)，a5=(2+1)×16−1=47。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40637","module":"shuliang","prompt":"6个正整数之和为30（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["24","30","26","25"],"answer":3,"explanation":"要使最大的数最大，其余5个数都取最小值1，故最大数=30−5×1=25。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40638","module":"shuliang","prompt":"某商品进价700元，售价1183元。该商品的利润率是多少？","options":["72%","69%","62%","138%"],"answer":1,"explanation":"利润=1183−700=483元，利润率=483÷700×100%=69%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40639","module":"shuliang","prompt":"在一个边长为12厘米的正方形纸片内，剪一个最大的圆（圆的直径等于正方形边长，π取3.14）。剩下的纸片面积是多少平方厘米？","options":["27","144","40","31"],"answer":3,"explanation":"正方形面积=144平方厘米，最大圆半径为6厘米，圆面积=3.14×6²=113平方厘米，剩余=144−113=31平方厘米。","exam":"通用基础","__sub":"几何问题","diff":3},{"id":"sl-40640","module":"shuliang","prompt":"一项工程，王师傅单独做需要10天完成，赵师傅单独做需要15天完成。两人（队）合作，需要多少天完成？","options":["25","6","5","13"],"answer":1,"explanation":"把工程总量看作1，两人效率之和为1/10+1/15=(10+15)/150，合作需要150÷(10+15)=6天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40641","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才6岁。”乙对甲说：“当我到你这么大时，你就33岁了。”甲今年多少岁？","options":["22","15","25","24"],"answer":3,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙6岁，即乙现在为x+d；乙到甲现在这么大时甲33岁，即甲现在为y−d。由y−d−(x+d)=d得d=(33−6)÷3=9，甲今年=33−9=24岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40642","module":"shuliang","prompt":"一个圆的半径为10厘米（π取3.14），它的面积是多少平方厘米？","options":["314","62","355","277"],"answer":0,"explanation":"圆的面积=πr²=3.14×10×10=314平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40643","module":"shuliang","prompt":"把308个名额按7:6:9的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["126","84","182","127"],"answer":0,"explanation":"总份数=7+6+9=22，每份308÷22=14个，最多的班级分得9×14=126个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40644","module":"shuliang","prompt":"甲在乙后方132千米处，两人同时同向出发。甲每小时行79千米，乙每小时行46千米，经过多少小时甲追上乙？","options":["4","6","132","79"],"answer":0,"explanation":"每小时甲比乙多行79-46=33千米，追及时间=132÷33=4小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40645","module":"shuliang","prompt":"一项工程，一队的工作效率是二队的1倍，两人合作28天完成。若由一队单独做，需要多少天完成？","options":["55","28","57","56"],"answer":3,"explanation":"设二队每天完成1份，则一队每天完成1份，两人合作每天2份，工程总量为28×2=56份；一队单独做需56÷1=56天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40646","module":"shuliang","prompt":"客车在货车后方74千米处，两人同时同向出发。客车每小时行79千米，货车每小时行42千米，经过多少小时客车追上货车？","options":["74","3","4","2"],"answer":3,"explanation":"每小时客车比货车多行79-42=37千米，追及时间=74÷37=2小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40647","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有30人，参加羽毛球赛的有31人，参加乒乓球赛的有33人；同时参加篮球和羽毛球的有11人，参加篮球和乒乓球的有7人，参加羽毛球和乒乓球的有9人，三项都参加的有5人。只参加其中一项比赛的有多少人？","options":["53","56","55","72"],"answer":2,"explanation":"只参加篮球=30−11−7+5=17人；同理只参加羽毛球=16人，只参加乒乓球=22人；合计17+16+22=55人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40648","module":"shuliang","prompt":"某商品进价每件40元，售价每件80元时每天可卖168件。售价每提高1元，每天少卖3件。要使每天利润最大，售价应定为每件多少元？","options":["92","88","86","80"],"answer":1,"explanation":"设售价提高k元，每天利润=(40+k)×(168−3k)，是关于k的二次函数，当k=8时最大，此时售价=80+8=88元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40649","module":"shuliang","prompt":"某班共有42人，参加数学竞赛的有22人，参加作文竞赛的有16人，参加英语竞赛的有17人；同时参加数学和作文的有7人，参加数学和英语的有5人，参加作文和英语的有9人，三项都参加的有2人。三项竞赛都不参加的有多少人？","options":["10","6","21","42"],"answer":1,"explanation":"至少参加一项的有22+16+17−7−5−9+2=36人，都不参加的有42−36=6人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40650","module":"shuliang","prompt":"已知等比数列的首项为2，公比为3，则它的第6项是多少？","options":["1458","486","162","489"],"answer":1,"explanation":"等比数列第n项=首项×公比^(n−1)=2×3^(6-1)=486。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40651","module":"shuliang","prompt":"甲接水需要8分钟，乙接水需要9分钟，丙接水需要3分钟，丁接水需要6分钟，戊接水需要11分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["88","100","55","37"],"answer":2,"explanation":"让用时短的人先接水可使总等待时间最短。按3、6、8、9、11的顺序，总等待=3×4+6×3+8×2+9×1+11×0=55分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40652","module":"shuliang","prompt":"甲数与乙数之比为5:4，乙数与丙数之比为4:2。甲数是丙数的多少倍？","options":["5/2","2/5","21/8","5/8"],"answer":0,"explanation":"甲:丙=5×4:4×2=20:8，甲是丙的5/2倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40653","module":"shuliang","prompt":"已知等比数列的首项为3，公比为2，则它的第5项是多少？","options":["24","96","48","50"],"answer":2,"explanation":"等比数列第n项=首项×公比^(n−1)=3×2^(5-1)=48。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40654","module":"shuliang","prompt":"甲接水需要8分钟，乙接水需要9分钟，丙接水需要6分钟，丁接水需要12分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["43","82","74","35"],"answer":0,"explanation":"让用时短的人先接水可使总等待时间最短。按6、8、9、12的顺序，总等待=6×3+8×2+9×1+12×0=43分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40655","module":"shuliang","prompt":"5个正整数之和为58（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["58","54","53","55"],"answer":1,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=58−4×1=54。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40656","module":"shuliang","prompt":"轿车、面包车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地36千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地42千米处。问A、B两地相距多少千米？","options":["75","89","52","108"],"answer":0,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且轿车行36千米，故第二次相遇时轿车共行108千米。108大于一个全程而小于两个全程，说明轿车已从B地折返，其位置距A地为2S−108（S为全程）。由2S−108=42，解得S=75千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40657","module":"shuliang","prompt":"已知等差数列的前10项和为315，前20项和为1130，则该数列的公差是多少？","options":["5","6","4","1"],"answer":0,"explanation":"S20−2×S10=(1130)−2×(315)=500=100d（第11到20项之和比前10项之和多100d），故d=5。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40658","module":"shuliang","prompt":"快车和慢车分别从相距348千米的两地同时出发，相向而行。快车每小时行48千米，慢车每小时行68千米，经过多少小时两车相遇？","options":["2","4","3","68"],"answer":2,"explanation":"两车速度之和为48+68=116千米/小时，相遇时间=348÷116=3小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40659","module":"shuliang","prompt":"某商品进价每件30元，售价每件60元时每天可卖184件。售价每提高1元，每天少卖4件。要使每天利润最大，售价应定为每件多少元？","options":["70","68","66","60"],"answer":1,"explanation":"设售价提高k元，每天利润=(30+k)×(184−4k)，是关于k的二次函数，当k=8时最大，此时售价=60+8=68元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40660","module":"shuliang","prompt":"某商品按定价出售每件可赚70元，若按定价的9折出售，每件将亏损50元。该商品的进价是多少元？","options":["1140","1130","1108","120"],"answer":1,"explanation":"设进价为C，定价为C+70；9折售价为9/10×(C+70)=C−50，解得C=1130元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40661","module":"shuliang","prompt":"4个正整数之和为37（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["38","37","34","33"],"answer":2,"explanation":"要使最大的数最大，其余3个数都取最小值1，故最大数=37−3×1=34。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40662","module":"shuliang","prompt":"一个长方形的长为19米，宽为17米，它的周长是多少米？","options":["36","323","72","74"],"answer":2,"explanation":"长方形周长=2×（长+宽）=2×(19+17)=72米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40663","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是21立方分米。圆锥的体积是多少立方分米？","options":["10","21","7","42"],"answer":2,"explanation":"等底等高的圆锥体积是圆柱的1/3，即21÷3=7立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40664","module":"shuliang","prompt":"把126个名额按7:3:8的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["57","21","70","56"],"answer":3,"explanation":"总份数=7+3+8=18，每份126÷18=7个，最多的班级分得8×7=56个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40665","module":"shuliang","prompt":"已知等比数列的首项为2，公比为3，则它的第5项是多少？","options":["54","486","162","165"],"answer":2,"explanation":"等比数列第n项=首项×公比^(n−1)=2×3^(5-1)=162。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40666","module":"shuliang","prompt":"已知等比数列的首项为4，公比为2，则它的第6项是多少？","options":["64","256","128","130"],"answer":2,"explanation":"等比数列第n项=首项×公比^(n−1)=4×2^(6-1)=128。","exam":"通用基础","__sub":"数列问题","diff":2}]);